(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const setV = (el, v) => { const d = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el), 'value').set; d.call(el, v); el.dispatchEvent(new Event('input', { bubbles: true })); };
  const cardOf = (text) => [...document.querySelectorAll('.pj-card')].find((c) => (c.innerText || '').includes(text));
  const out = {};
  document.querySelector('.tb-project-main').click();
  await sleep(3000);
  out.title = document.querySelector('.pj-title')?.textContent || null;
  out.navLinks = [...document.querySelectorAll('header a')].map((a) => a.textContent.trim()).filter(Boolean).join('/');
  out.crumb = (document.querySelector('.pj-crumb')?.innerText || '').replace(/\s+/g, ' ');
  out.headActions = [...document.querySelectorAll('.pj-head-actions button')].map((b) => b.textContent.trim()).filter(Boolean).join(' | ');
  out.hasRecommend = (document.body.innerText || '').includes('相关项目推荐');
  out.metaText = (document.querySelector('.pj-meta')?.innerText || '').replace(/\s+/g, ' ');

  // === 1. 项目描述自主编辑 ===
  const card = cardOf('项目描述');
  const editBtn = card.querySelector('.pj-link-btn');
  editBtn.click();
  await sleep(400);
  const tas = card.querySelectorAll('textarea');
  out.textareas = tas.length;
  setV(tas[0], '本地测试：红外循迹小车能自己沿黑线跑完全程。');
  setV(tas[1], '识别黑线\n自动纠偏\n蜂鸣器提示');
  [...card.querySelectorAll('.pj-btn-primary')].find((b) => b.textContent.trim() === '保存').click();
  await sleep(1500);
  out.descAfterSave = (cardOf('项目描述')?.innerText || '').replace(/\s+/g, ' ').slice(0, 120);

  // === 2. 手动添加元件 ===
  const bom = cardOf('元器件清单');
  [...bom.querySelectorAll('.pj-link-btn')].find((b) => b.textContent.includes('添加元件')).click();
  await sleep(400);
  const inputs = cardOf('元器件清单').querySelectorAll('input');
  out.addInputs = inputs.length;
  setV(inputs[0], '测试电阻');
  setV(inputs[1], '电阻');
  setV(inputs[2], '10kΩ');
  setV(inputs[3], '2');
  [...cardOf('元器件清单').querySelectorAll('.pj-btn-primary')].find((b) => b.textContent.trim() === '加入作品').click();
  await sleep(1800);
  out.bomHasNew = (cardOf('元器件清单')?.innerText || '').includes('测试电阻');
  out.bomRows = document.querySelectorAll('.pj-table tbody tr').length;

  // === 3. AI 识别入口（未配置时应给引导而不是报错）===
  [...document.querySelectorAll('.pj-head-actions button')].find((b) => b.textContent.includes('AI 识别元件')).click();
  await sleep(1200);
  out.aiModalText = (document.querySelector('.lr-modal')?.innerText || '').replace(/\s+/g, ' ').slice(0, 160);
  document.querySelector('.lr-close')?.click();
  await sleep(300);

  // === 4. 分享作品弹层 ===
  [...document.querySelectorAll('.pj-head-actions button')].find((b) => b.textContent.includes('分享作品')).click();
  await sleep(1500);
  out.shareModalText = (document.querySelector('.sw-modal')?.innerText || '').replace(/\s+/g, ' ').slice(0, 140);
  document.querySelector('.sw-close')?.click();
  await sleep(300);
  return JSON.stringify(out);
})()
